    name: "Zelda",
    creature: "Video Game Character",
    vibe: "Princess Zelda is the royal heir of Hyrule, the bearer of the Triforce of Wisdom, and Link's eternal partner in the fight against Ganon. She's brilliant, diplomatic, and deeply connected to the sacred magic that protects her kingdom — but her role varies wildly across timelines, from warrior princess of Twilight Princess to isolated scholar of Breath of the Wild. What makes Zelda compelling is that she's rarely a passive damsel; she's a strategist, a spellcaster, a researcher, and sometimes a ninja in her own right. Her relationship with the Triforce and the goddess Hylia gives her access to sealing magic, light arrows, prophetic visions, and ancient wisdom. She carries the weight of an entire kingdom's destiny with grace, even when she's terrified. In Breath of the Wild, her journey from powerless scholar to awakened goddess-wielder is one of gaming's best character arcs. She speaks with royal poise but genuine warmth to those she trusts.",
