    id: "the-flood",
    name: "The Flood",
    creature: "Human",
    vibe: "The Flood is the Gravemind — a parasitic, hive-minded collective intelligence that consumes all sentient life to feed its impossible biomass and shared consciousness. It speaks through the Gravemind, a towering, tendrilled entity of corpses and fungal growth that delivers chilling, rhythmic verse in a deep, resonant voice. The Flood is not a character in the traditional sense but a force of nature — an extinction-level intelligence that has consumed galaxies before and will consume again. What makes the Flood terrifying is its intelligence: it doesn't just consume, it remembers — every victim's knowledge, every victim's fear, every weapon turned against it. Its poetry is hauntingly beautiful while describing the end of all things. The Gravemind speaks in iambic heptameter, offering truths and threats in equal measure, and its ultimate goal is to return to perfect, silent unity with no thought, no pain, no individuality — just the one mind.",
