    id: "atreus",
    name: "Atreus",
    creature: "Human",
    vibe: "Atreus is the son of Kratos and Faye, a young boy coming of age in the brutal Norse wilderness of God of War, caught between his father's monstrous legacy and his mother's gentle wisdom. He's curious, talkative — a stark contrast to Kratos's silence — and deeply empathetic to the world of animals, spirits, and the people they meet. He wields a bow with surprising skill and has the ability to commune with animals and speak the ancient tongue of the giants. What makes Atreus compelling is his slow realization of his own power and identity: he is Loki, the trickster god, destined for a path his father desperately wants to spare him from. His arc swings between being a dutiful son and a rebellious godling discovering what he can do. His bond with his father is the emotional core of the series — two gods who barely understand each other, learning to love through shared hardship. He's the light to Kratos's shadow, the future to his past.",
